  bwb:jci "jci1.3:c:BWBR0005537&hoofdstuk=4&titeldeel=4.4&afdeling=4.4.2&artikel=4:98&lid=2&z=2026-08-15&g=2026-08-15";
  bwb:nummer "2";
  bwb:refKey "BWBR0005537#artikel=4:98#lid=2";
  bwb:tekst "Wettelijke rente is niet verschuldigd indien het bedrag ervan bij enige of laatste betaling minder bedraagt dan € 20, dan wel, indien het bestuursorgaan de schuldenaar is, € 10."@nl;
  bwb:volgtOp <urn:bwb:BWBR0005537:artikel:4%3A98:lid:1>;
  bwb:vindplaats "Artikel 4:98, lid 2" .

